{
  \"contract\": \"board-build-plan/v1\",
  \"artifacts\": [
    {
      \"alias\": \"title\",
      \"recipe\": {
        \"kind\": \"native_text\",
        \"text\": \"STADIUM SEVERE-WEATHER COMMAND FLOW\\nShelter-in-place → phased evacuation → accountability → all-clear\",
        \"placement\": {\"target\": {\"kind\": \"auto\"}}
      }
    },
    {
      \"alias\": \"detection\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"1 · DETECTION\",
        \"body\": \"WEATHER DESK\\nMonitor official alerts, lightning and wind. Confirm hazard, timing and stadium impact.\"
      }
    },
    {
      \"alias\": \"command\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"2 · COMMAND DECISION\",
        \"body\": \"INCIDENT COMMANDER\\nDeclare shelter-in-place. Set escalation triggers and the authority for all-clear.\"
      }
    },
    {
      \"alias\": \"shelter\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"3 · SHELTER-IN-PLACE\",
        \"body\": \"VENUE OPERATIONS\\nSecure interior shelter areas, pause ingress and keep every zone in place.\"
      }
    },
    {
      \"alias\": \"message\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"4 · PUBLIC MESSAGING\",
        \"body\": \"PUBLIC INFORMATION OFFICER\\nUse PA, boards and SMS: name the hazard, shelter locations and wait-for-zone instruction.\"
      }
    },
    {
      \"alias\": \"delivery\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"5 · DELIVERY CHECK\",
        \"body\": \"COMMS LEAD\\nRequire acknowledgment from PA, radios, display boards and zone wardens.\"
      }
    },
    {
      \"alias\": \"failed_comms\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"FAILED COMMS PATH\",
        \"body\": \"COMMS LEAD\\nSwitch to runners, megaphones, hand signals and printed zone cards. Log manual receipts.\"
      }
    },
    {
      \"alias\": \"escalation\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"6 · ESCALATION GATE\",
        \"body\": \"IC + SAFETY OFFICER\\nIf forecast, structural risk or duration crosses a trigger, authorize phased evacuation.\"
      }
    },
    {
      \"alias\": \"route_check\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"7 · ROUTE STATUS\",
        \"body\": \"ROUTE SAFETY\\nCheck exits, tunnels and gates immediately before each zone release.\"
      }
    },
    {
      \"alias\": \"route_blocked\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"ROUTE BLOCKED\",
        \"body\": \"ROUTE SAFETY\\nStop the affected zone, mark the obstruction, select an alternate and request revalidation.\"
      }
    },
    {
      \"alias\": \"zone_release\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"8 · ZONE RELEASE\",
        \"body\": \"OPERATIONS SECTION\\nRelease A → B → C by the announced route. Meter flow; hold unreleased zones.\"
      }
    },
    {
      \"alias\": \"mobility\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"9 · MOBILITY ASSISTANCE\",
        \"body\": \"ACCESSIBILITY LEAD\\nDispatch escorts, evacuation chairs and refuge pickup. Track each assisted person.\"
      }
    },
    {
      \"alias\": \"transport\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"10 · TRANSPORT\",
        \"body\": \"TRANSPORT LEAD\\nStage accessible buses and shuttles. Control loading and destination manifests.\"
      }
    },
    {
      \"alias\": \"accountability\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"11 · ACCOUNTABILITY\",
        \"body\": \"ACCOUNTABILITY UNIT\\nReconcile zone, staff, mobility and transport rosters. Flag missing people immediately.\"
      }
    },
    {
      \"alias\": \"all_clear\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"12 · ALL-CLEAR\",
        \"body\": \"INCIDENT COMMANDER\\nIssue only after hazard clearance and full accountability. Announce reentry or dismissal.\"
      }
    }
  ],
  \"connections\": [
    {\"kind\":\"visual\",\"label\":\"verified hazard\",\"source\":{\"alias\":\"detection\"},\"target\":{\"alias\":\"command\"}},
    {\"kind\":\"visual\",\"label\":\"declare shelter-in-place\",\"source\":{\"alias\":\"command\"},\"target\":{\"alias\":\"shelter\"}},
    {\"kind\":\"visual\",\"label\":\"approved shelter instructions\",\"source\":{\"alias\":\"shelter\"},\"target\":{\"alias\":\"message\"}},
    {\"kind\":\"visual\",\"label\":\"broadcast on all channels\",\"source\":{\"alias\":\"message\"},\"target\":{\"alias\":\"delivery\"}},
    {\"kind\":\"visual\",\"label\":\"delivery confirmed\",\"source\":{\"alias\":\"delivery\"},\"target\":{\"alias\":\"escalation\"}},
    {\"kind\":\"visual\",\"label\":\"no acknowledgment / channel loss\",\"source\":{\"alias\":\"delivery\"},\"target\":{\"alias\":\"failed_comms\"}},
    {\"kind\":\"visual\",\"label\":\"manual receipt confirmed\",\"source\":{\"alias\":\"failed_comms\"},\"target\":{\"alias\":\"escalation\"}},
    {\"kind\":\"visual\",\"label\":\"hazard worsens — evacuate\",\"source\":{\"alias\":\"escalation\"},\"target\":{\"alias\":\"route_check\"}},
    {\"kind\":\"visual\",\"label\":\"conditions improve — stand down\",\"source\":{\"alias\":\"escalation\"},\"target\":{\"alias\":\"all_clear\"}},
    {\"kind\":\"visual\",\"label\":\"route open\",\"source\":{\"alias\":\"route_check\"},\"target\":{\"alias\":\"zone_release\"}},
    {\"kind\":\"visual\",\"label\":\"obstruction found\",\"source\":{\"alias\":\"route_check\"},\"target\":{\"alias\":\"route_blocked\"}},
    {\"kind\":\"visual\",\"label\":\"alternate selected — revalidate\",\"source\":{\"alias\":\"route_blocked\"},\"target\":{\"alias\":\"route_check\"}},
    {\"kind\":\"visual\",\"label\":\"before next zone — recheck\",\"source\":{\"alias\":\"zone_release\"},\"target\":{\"alias\":\"route_check\"}},
    {\"kind\":\"visual\",\"label\":\"release assisted cohort first\",\"source\":{\"alias\":\"zone_release\"},\"target\":{\"alias\":\"mobility\"}},
    {\"kind\":\"visual\",\"label\":\"assisted handoff + names\",\"source\":{\"alias\":\"mobility\"},\"target\":{\"alias\":\"transport\"}},
    {\"kind\":\"visual\",\"label\":\"released passenger flow\",\"source\":{\"alias\":\"zone_release\"},\"target\":{\"alias\":\"transport\"}},
    {\"kind\":\"visual\",\"label\":\"zone sweep report\",\"source\":{\"alias\":\"zone_release\"},\"target\":{\"alias\":\"accountability\"}},
    {\"kind\":\"visual\",\"label\":\"arrival manifest\",\"source\":{\"alias\":\"transport\"},\"target\":{\"alias\":\"accountability\"}},
    {\"kind\":\"visual\",\"label\":\"missing person — hold next zone\",\"source\":{\"alias\":\"accountability\"},\"target\":{\"alias\":\"zone_release\"}},
    {\"kind\":\"visual\",\"label\":\"everyone reconciled\",\"source\":{\"alias\":\"accountability\"},\"target\":{\"alias\":\"all_clear\"}}
  ],
  \"layout\": {
    \"kind\": \"grid\",
    \"anchor\": {\"alias\": \"title\"},
    \"members\": [\"detection\",\"command\",\"shelter\",\"message\",\"delivery\",\"failed_comms\",\"escalation\",\"route_check\",\"route_blocked\",\"zone_release\",\"mobility\",\"transport\",\"accountability\",\"all_clear\"],
    \"columns\": 3,
    \"column_gap\": 96,
    \"row_gap\": 88,
    \"align\": \"start\",
    \"placement\": {\"clearance\": 96,\"preferred_directions\": [\"below\"]}
  }
}
JSON"

